function computeBalanceOutGivenInvariant(
    uint256 currentBalance,
    uint256 weight,
    uint256 invariantRatio
) internal pure returns (uint256) {
    // Protect against extreme calculations
    require(weight >= MIN_WEIGHT, "Weight too small");
    require(currentBalance <= MAX_BALANCE, "Balance too large");
    require(invariantRatio <= MAX_INVARIANT_RATIO, "Ratio too large");

    // Safe calculation with bounds checking
    uint256 exponent = FixedPoint.divDown(FixedPoint.ONE, weight);
    require(exponent <= MAX_SAFE_EXPONENT, "Exponent too large");

    return currentBalance * LogExpMath.pow(invariantRatio, exponent);
}

